mapper.select:
SELECT c.*, (SELECT COUNT(*) FROM condition_controller_file f WHERE f.controller_id = c.id AND f.half = 'H1') AS h1_file_count, (SELECT COUNT(*) FROM condition_controller_file f WHERE f.controller_id = c.id AND f.half = 'H2') AS h2_file_count FROM condition_controller c WHERE c.use_yn = 'Y' AND c.calib_year = #{calibYear}
AND c.equip_name = #{equipName}
ORDER BY c.equip_name ASC, c.zone_name ASC, c.id DESC
